from itertools import groupby

def group_tuples(tuples_list):
    tuples_list.sort()
    result = []
    for key, group in groupby(tuples_list, key=lambda x: x[0]):
        group_list = list(group)
        if len(group_list) > 1:
            combined = list(group_list[0])
            for t in group_list[1:]:
                combined.extend(t[1:])
            result.append(tuple(combined))
        else:
            result.append(group_list[0])
    return result
